import { PrismaPg } from "@prisma/adapter-pg";
import { Client as SurrealClient } from "@surrealdb/pg";
import pg from "pg";
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { startEngine } from "./harness";

// Generated by `bun run prisma:generate` (a pretest step in CI)
type PrismaClientLike = {
    user: any;
    post: any;
    $transaction: any;
    $disconnect(): Promise<void>;
};

let ctx: Awaited<ReturnType<typeof startEngine>>;
let pool: pg.Pool;
let prisma: PrismaClientLike;

beforeAll(async () => {
    ctx = await startEngine();
    pool = new pg.Pool({ ...ctx.options, Client: SurrealClient as never, max: 3 });
    await pool.query(
        `create table "User" (id serial primary key, email text not null unique, name text)`,
    );
    await pool.query(
        `create table "Post" (id serial primary key, title text not null, "authorId" integer not null references "User"(id))`,
    );
    const mod = (await import("./prisma/generated/client.ts").catch((e) => {
        throw new Error(`Run \`bun run prisma:generate\` first: ${e.message}`);
    })) as { PrismaClient: new (o: unknown) => PrismaClientLike };
    prisma = new mod.PrismaClient({ adapter: new PrismaPg(pool) });
}, 60_000);
afterAll(async () => {
    await prisma?.$disconnect();
    await pool?.end();
    await ctx?.engine.close();
});

describe("Prisma adapter-pg over pg.Pool({ Client: SurrealDB Client })", () => {
    it("creates with a nested relation and reads it back with a relation join", async () => {
        const user = await prisma.user.create({
            data: {
                email: "a@x.io",
                name: "Ann",
                posts: { create: [{ title: "one" }, { title: "two" }] },
            },
            include: { posts: true },
        });
        expect(user.posts).toHaveLength(2);
        const found = await prisma.user.findMany({
            where: { email: "a@x.io" },
            include: { posts: { orderBy: { id: "asc" } } },
        });
        expect(found[0].posts.map((p: { title: string }) => p.title)).toEqual(["one", "two"]);
    });

    it("maps a unique violation to P2002", async () => {
        const error: any = await prisma.user
            .create({ data: { email: "a@x.io" } })
            .catch((e: unknown) => e);
        expect(error.code).toBe("P2002");
    });

    it("runs an interactive transaction and rolls it back", async () => {
        await expect(
            prisma.$transaction(async (tx: PrismaClientLike) => {
                await tx.user.create({ data: { email: "rolled@x.io" } });
                throw new Error("abort");
            }),
        ).rejects.toThrow("abort");
        expect(await prisma.user.count({ where: { email: "rolled@x.io" } })).toBe(0);
        await prisma.$transaction(async (tx: PrismaClientLike) => {
            await tx.user.create({ data: { email: "kept@x.io" } });
        });
        expect(await prisma.user.count({ where: { email: "kept@x.io" } })).toBe(1);
    });

    it("runs a batch transaction", async () => {
        const [a, b] = await prisma.$transaction([prisma.user.count(), prisma.post.count()]);
        expect(a).toBeGreaterThanOrEqual(2);
        expect(b).toBe(2);
    });
});
